async function block(root,name,size,pos,mat,r=0.08){const g=await roundedBoxGeo(...size,Math.min(...size)*r,{style:'chamfer'});return createPart(name,g,mat,{position:pos,parent:root});}
const meta={name:'cable-junction',role:'prop'};
async function build(){const root=createRoot('cable-junction'),m=styleMaterials();
await block(root,'base',[0.68,0.14,0.54],[0,0.07,0],m.panelGray,0.3);await block(root,'orange housing',[0.64,0.35,0.5],[0,0.315,0],m.accent,0.18);
await block(root,'interior floor',[0.53,0.045,0.39],[0,0.5,0],m.trim);for(const x of [-0.295,0.295])await block(root,'rim side',[0.07,0.1,0.5],[x,0.51,0],m.panelGray,0.2);for(const z of [-0.215,0.215])await block(root,'rim edge',[0.53,0.1,0.07],[0,0.51,z],m.panel,0.2);
for(const x of [-0.2,0,0.2])await block(root,'terminal',[0.11,0.04,0.18],[x,0.54,0],m.panelGray);
for(const x of [-0.38,0.38]){createPart('cable connector',cylinderGeo(0.075,0.075,0.12,8),m.panelGray,{position:[x,0.3,0],rotation:[0,0,90],parent:root});}
const lid=new THREE.Group();lid.name='lid';lid.position.set(0,0.56,-0.23);root.add(lid);await block(lid,'lid panel',[0.65,0.38,0.065],[0,0.19,-0.015],m.panel,0.25);await block(lid,'lid inset',[0.51,0.26,0.015],[0,0.19,0.025],m.panelGray,0.25);await block(lid,'lid latch',[0.12,0.055,0.04],[0,0.36,0.04],m.trim);
return root;}
